69	    /**
70	     * 모든 사용자 알림 생성
71	     */
72	    public List<NotificationDTO> createNotificationForAll(NotificationRequestDTO requestDTO) {
73	        try {
74	            List<User> allUsers = userRepository.findAll();
75	            if (allUsers.isEmpty()) {
76	                log.warn("알림 대상 사용자가 없습니다.");
77	                return List.of();
78	            }
79	
80	            log.info("전체 사용자 알림 생성 시작: 카테고리={}, 타입={}, 대상 사용자 수={}",
81	                    requestDTO.getCategory(), requestDTO.getType(), allUsers.size());
82	
83	            List<Notification> notifications = createNotificationsForUsers(
84	                    allUsers, requestDTO.getCategory(), requestDTO.getType(), requestDTO.getMessage());
85	
86	            List<Notification> savedNotifications = notificationRepository.saveAll(notifications);
87	            log.info("전체 사용자 알림 생성 완료: 카테고리={}, 타입={}, 생성된 알림 수={}",
88	                    requestDTO.getCategory(), requestDTO.getType(), savedNotifications.size());
89	
90	            // 연결된 사용자에게만 실시간 알림 전송
91	            broadcastNotificationsToConnectedUsers(allUsers, savedNotifications);
92	
93	            return toDTOList(savedNotifications);
94	        } catch (Exception e) {
95	            log.error("전체 사용자 알림 생성 중 오류 발생: 카테고리={}, 타입={}, 오류={}",
96	                    requestDTO.getCategory(), requestDTO.getType(), e.getMessage(), e);
97	            throw new NotificationException(NotificationErrorCode.NOTIFICATION_CREATION_FAILED, e);
98	        }
99	    }
100	
101	    /**
102	     * 알림 읽음 처리
103	     */
104	    public void markAsRead(Long notificationId, String email) {
105	        try {
106	            Notification notification = notificationRepository.findById(notificationId)
107	                    .orElseThrow(() -> new NotificationException(
108	                            NotificationErrorCode.NOTIFICATION_NOT_FOUND,
109	                            "알림 ID: " + notificationId + "를 찾을 수 없습니다."
110	                    ));
111	
112	            // 알림의 사용자 이메일과 요청한 이메일이 일치하는지 확인
113	            if (!notification.getUser().getEmail().equals(email)) {
114	                log.warn("알림 읽음 처리 권한 없음: 알림ID={}, 요청자={}, 소유자={}",
115	                        notificationId, email, notification.getUser().getEmail());
116	                throw new NotificationException(
117	                        NotificationErrorCode.NOTIFICATION_ACCESS_DENIED,
118	                        "해당 알림은 현재 사용자에게 속하지 않습니다."
119	                );
120	            }
121	
122	            notification.markAsRead(); // 읽음 처리
123	            log.info("알림 읽음 처리 완료: 알림ID={}, 사용자={}", notificationId, email);
124	        } catch (NotificationException e) {
125	            throw e; // 이미 NotificationException이면 그대로 전파
126	        } catch (Exception e) {
127	            log.error("알림 읽음 처리 중 오류 발생: 알림ID={}, 사용자={}, 오류={}",
128	                    notificationId, email, e.getMessage(), e);
129	            throw new NotificationException(
130	                    NotificationErrorCode.NOTIFICATION_READ_FAILED,
131	                    "알림 읽음 처리 중 오류가 발생했습니다.",
132	                    e
133	            );
134	        }
135	    }
136	
137	    /**
138	     * 모든 알림 읽음 처리 (추가된 기능)
139	     */
140	    public void markAllAsRead(String email) {
141	        try {
142	            List<Notification> notifications = notificationRepository.findAllByUserEmail(email);
143	            if (notifications.isEmpty()) {
144	                log.info("읽음 처리할 알림이 없습니다: 사용자={}", email);
145	                return;
146	            }
147	
148	            for (Notification notification : notifications) {
149	                if (!notification.isRead()) {
150	                    notification.markAsRead();
151	                }
152	            }
153	
154	            log.info("모든 알림 읽음 처리 완료: 사용자={}, 처리된 알림 수={}", email, notifications.size());
155	        } catch (Exception e) {
156	            log.error("알림 읽음 처리 중 오류 발생: 사용자={}, 오류={}", email, e.getMessage(), e);
157	            throw new NotificationException(
158	                    NotificationErrorCode.NOTIFICATION_READ_FAILED,
159	                    "알림 읽음 처리 중 오류가 발생했습니다.",
160	                    e
161	            );
162	        }
163	    }
164	
165	    /**
166	     * 알림 삭제
167	     */
168	    public void deleteNotification(Long notificationId) {
169	        try {
170	            // 삭제 전에 알림이 존재하는지 확인
171	            boolean exists = notificationRepository.existsById(notificationId);
172	            if (!exists) {
173	                throw new NotificationException(
174	                        NotificationErrorCode.NOTIFICATION_NOT_FOUND,
175	                        "삭제할 알림을 찾을 수 없습니다. ID: " + notificationId
176	                );
177	            }
178	
179	            notificationRepository.deleteById(notificationId);
180	            log.info("알림 삭제 완료: 알림ID={}", notificationId);
181	        } catch (NotificationException e) {
182	            throw e; // 이미 NotificationException이면 그대로 전파
183	        } catch (Exception e) {
184	            log.error("알림 삭제 중 오류 발생: 알림ID={}, 오류={}", notificationId, e.getMessage(), e);
185	            throw new NotificationException(
186	                    NotificationErrorCode.NOTIFICATION_DELETE_FAILED,
187	                    "알림 삭제 중 오류가 발생했습니다.",
188	                    e
189	            );
190	        }
191	    }
192	
193	    /**
194	     * 사용자 알림 전체 삭제
195	     */
196	    public void deleteNotificationsByUser(String email) {
197	        try {
198	            List<Notification> notifications = notificationRepository.findAllByUserEmail(email);
199	            if (notifications.isEmpty()) {
200	                log.info("삭제할 알림이 없습니다: 사용자={}", email);
201	                return;
202	            }
203	
204	            notificationRepository.deleteAll(notifications);
205	            log.info("사용자 알림 전체 삭제 완료: 사용자={}, 삭제된 알림 수={}", email, notifications.size());
206	        } catch (Exception e) {
207	            log.error("사용자 알림 삭제 중 오류 발생: 사용자={}, 오류={}", email, e.getMessage(), e);
208	            throw new NotificationException(
209	                    NotificationErrorCode.NOTIFICATION_DELETE_FAILED,
210	                    "사용자 알림 삭제 중 오류가 발생했습니다.",
211	                    e
212	            );
213	        }
214	    }
215	
216	    /**
217	     * 배송 완료 알림 생성
218	     */
219	    public void notifyShipmentCompleted(Order order) {
220	        try {
221	            User buyer = order.getUser();
222	            log.info("배송 완료 알림 생성: 주문ID={}, 사용자ID={}", order.getId(), buyer.getId());
223	
224	            createNotification(
225	                    buyer.getId(),
226	                    NotificationCategory.SHOPPING,
227	                    NotificationType.BID,
228	                    "[배송 완료] 상품이 배송 완료되었습니다. 주문 ID: " + order.getId()
229	            );
230	        } catch (Exception e) {
231	            // 비즈니스 로직 중단을 방지하기 위해 예외를 로깅만 함
232	            log.error("배송 완료 알림 생성 중 오류 발생: 주문ID={}, 오류={}", order.getId(), e.getMessage(), e);
233	        }
234	    }
235	
236	    // ==================== 헬퍼 메서드 ====================
237	
238	    /**
239	     * Notification 엔티티 생성
240	     */
241	    private Notification buildNotification(User user, NotificationCategory category, NotificationType type, String message) {
242	        return Notification.builder()
243	                .category(category)
244	                .type(type)
245	                .message(message)
246	                .isRead(false)
247	                .user(user)
248	                .build();
249	    }
250	
251	    /**
252	     * 여러 사용자를 위한 알림 엔티티 생성
253	     */
254	    private List<Notification> createNotificationsForUsers(
255	            List<User> users, NotificationCategory category, NotificationType type, String message) {
256	        List<Notification> notifications = new ArrayList<>();
257	
258	        for (User user : users) {
259	            Notification notification = buildNotification(user, category, type, message);
260	            notifications.add(notification);
261	        }
262	
263	        return notifications;
264	    }
265	
266	    /**
267	     * 연결된 사용자들에게 실시간 알림 브로드캐스트
268	     */
269	    private void broadcastNotificationsToConnectedUsers(List<User> users, List<Notification> notifications) {
270	        int deliveredCount = 0;
271	
272	        for (User user : users) {
273	            String redisKey = REDIS_KEY_PREFIX + user.getEmail();
274	
275	            if (Boolean.TRUE.equals(redisTemplate.hasKey(redisKey))) {
276	                try {
277	                    // 해당 사용자의 알림만 필터링
278	                    List<NotificationDTO> userNotifications = notifications.stream()
279	                            .filter(notification -> notification.getUser().getId().equals(user.getId()))
280	                            .map(this::toDTO)
281	                            .collect(Collectors.toList());
282	
283	                    // 실시간 알림 전송
284	                    messagingTemplate.convertAndSendToUser(
285	                            user.getEmail(),
286	                            WEBSOCKET_DESTINATION,
287	                            userNotifications
288	                    );
289	                    deliveredCount++;
290	                } catch (Exception e) {
291	                    log.warn("사용자 알림 실시간 전송 실패: 사용자={}, 오류={}", user.getEmail(), e.getMessage());
292	                    // 개별 전송 실패는 무시하고 계속 진행
293	                }
294	            }
295	        }
296	
297	        log.info("실시간 알림 전송 완료: 총 {}명 중 {}명에게 전송됨", users.size(), deliveredCount);
298	    }
299	
300	    /**
301	     * 단일 사용자에게 실시간 알림 전송
302	     */
303	    private void sendRealTimeNotification(String email, NotificationDTO notification) {
304	        String redisKey = REDIS_KEY_PREFIX + email;
305	
306	        // 연결된 사용자에게만 알림 전송
307	        if (Boolean.TRUE.equals(redisTemplate.hasKey(redisKey))) {
308	            try {
309	                messagingTemplate.convertAndSendToUser(
310	                        email,
311	                        WEBSOCKET_DESTINATION,
312	                        notification
313	                );
314	                log.debug("알림 실시간 전송 완료: 사용자={}, 알림ID={}", email, notification.getId());
315	            } catch (Exception e) {
316	                log.warn("알림 실시간 전송 실패: 사용자={}, 알림ID={}, 오류={}",
317	                        email, notification.getId(), e.getMessage());
318	                // 실시간 전송 실패해도 알림은 이미 저장되었으므로 예외 발생시키지 않음
319	            }
320	        } else {
321	            log.debug("사용자 WebSocket 연결 없음: 사용자={}, 알림은 저장됨", email);
322	        }
323	    }
324	
325	    /**
326	     * WebSocket 연결 유지를 위한 Redis TTL 업데이트
327	     */
328	    public void updateWebSocketConnectionTTL(String email) {
329	        try {
330	            if (email != null) {
331	                String redisKey = REDIS_KEY_PREFIX + email;
332	
333	                // 남은 TTL(초 단위)
334	                Long remainingTime = redisTemplate.getExpire(redisKey, TimeUnit.SECONDS);
335	
336	                // TTL이 10분 이하인 경우만 30분으로 갱신
337	                if (remainingTime != null && remainingTime <= 600) {
338	                    redisTemplate.expire(redisKey, REDIS_TTL_MINUTES, TimeUnit.MINUTES);
339	                    log.debug("Redis TTL 갱신: 사용자={}, 남은TTL={}초", email, remainingTime);
340	                } else {
341	                    log.debug("TTL 연장 불필요: 사용자={}, 남은TTL={}초", email, remainingTime);
342	                }
343	            }
344	        } catch (Exception e) {
345	            log.error("WebSocket 연결 TTL 갱신 중 오류 발생: 사용자={}, 오류={}", email, e.getMessage(), e);
346	            throw new NotificationException(
347	                    NotificationErrorCode.WEBSOCKET_CONNECTION_MAINTENANCE_FAILED,
348	                    "WebSocket 연결 유지 중 오류가 발생했습니다.",
349	                    e
350	            );
351	        }
352	    }
353	
354	    /**
355	     * DTO 변환 메서드
356	     */
357	    private NotificationDTO toDTO(Notification notification) {
358	        return NotificationDTO.builder()
359	                .id(notification.getId())
360	                .category(notification.getCategory())
361	                .type(notification.getType())
362	                .message(notification.getMessage())
363	                .isRead(notification.isRead())
364	                .createdAt(notification.getCreatedDate().toString())
365	                .build();
366	    }
367	
368	    /**
369	     * 알림 목록을 DTO 목록으로 변환
370	     */
371	    private List<NotificationDTO> toDTOList(List<Notification> notifications) {
372	        return notifications.stream()
373	                .map(this::toDTO)
374	                .collect(Collectors.toList());
375	    }
376	}

