    for (Interest interest : interestRepository.findAllByProductColorId(productSize.getProductColor().getId())) {
        User interestedUser = interest.getUser();
        if (interestedUser.getId().equals(seller.getId()) || !interestedUser.isActive()) {
            continue;
        }
        notificationCommandService.createNotification(
                interestedUser.getId(),
                NotificationCategory.SHOPPING,
                NotificationType.FAVORITE,
                message
        );
    }
}

